    /// <summary>Opciones (clave, etiqueta) para el selector de iconos del formulario.</summary>
    public static IReadOnlyList<(string Key, string Label)> Options { get; } = new List<(string, string)>
    {
        ("chart", "Actividad"), ("bar", "Barras"), ("pie", "Torta"), ("trend", "Tendencia"),
        ("sales", "Ventas"), ("finance", "Finanzas"), ("money", "Dinero"), ("people", "Personas"),
        ("dashboard", "Tablero"), ("report", "Reporte"), ("database", "Base de datos"), ("building", "Edificio"),
        ("cart", "Compras"), ("box", "Inventario"), ("layers", "Capas"), ("globe", "Web"),
        ("briefcase", "Negocios"), ("settings", "Configuracion")
    };

    /// <summary>Devuelve el SVG completo (HTML seguro, claves controladas internamente).</summary>
    public static string Render(string? key, int size = 24)
    {
        var inner = key != null && Icons.TryGetValue(key, out var v) ? v : Icons["chart"];
        return $"""<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>""";
    }
}
